(() => {
  const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;const lowPower=navigator.hardwareConcurrency&&navigator.hardwareConcurrency<=4;if(reduce)return;const css=document.createElement('style');css.textContent=`.mtgx-light-beam{position:fixed;z-index:-1;pointer-events:none;width:14vw;height:120vh;top:-10vh;left:-20vw;background:linear-gradient(90deg,transparent,rgba(109,159,255,.06),rgba(255,255,255,.06),transparent);filter:blur(14px);transform:rotate(18deg);animation:mtgx-beam 30s linear infinite}.mtgx-depth-orb{position:fixed;z-index:-1;pointer-events:none;border-radius:50%;filter:blur(32px);opacity:.11;mix-blend-mode:screen;animation:mtgx-orb-drift 16s ease-in-out infinite alternate}.mtgx-depth-orb.one{width:210px;height:210px;right:8%;top:18%;background:#536dff}.mtgx-depth-orb.two{width:150px;height:150px;left:5%;bottom:14%;background:#16a7bd;animation-delay:-5s}.mtgx-cursor-trail{position:fixed;z-index:1200;pointer-events:none;width:6px;height:6px;border-radius:50%;background:#a9d8ff;box-shadow:0 0 12px 3px rgba(87,145,255,.35);transform:translate(-50%,-50%);opacity:0}.mtgx-section-glint{position:absolute;z-index:2;pointer-events:none;left:0;right:0;top:0;height:1px;background:linear-gradient(90deg,transparent,rgba(119,187,255,.45),transparent);box-shadow:0 0 12px rgba(76,126,255,.25);animation:mtgx-glint 8s ease-in-out infinite}@keyframes mtgx-beam{0%{left:-24vw;opacity:0}14%{opacity:.45}50%{opacity:.2}65%,100%{left:118vw;opacity:0}}@keyframes mtgx-orb-drift{from{transform:translate3d(-8px,5px,0)}to{transform:translate3d(10px,-10px,0)}}@keyframes mtgx-glint{0%,100%{opacity:.12;transform:scaleX(.6)}50%{opacity:.5;transform:scaleX(1)}}@media(max-width:700px){.mtgx-light-beam{display:none}.mtgx-depth-orb{filter:blur(24px);opacity:.07}}@media(prefers-reduced-motion:reduce){.mtgx-light-beam,.mtgx-depth-orb,.mtgx-cursor-trail,.mtgx-section-glint{display:none}}`;document.head.appendChild(css);const beam=document.createElement('div');beam.className='mtgx-light-beam';document.body.appendChild(beam);['one','two'].forEach(n=>{const o=document.createElement('div');o.className=`mtgx-depth-orb ${n}`;document.body.appendChild(o)});document.querySelectorAll('.hero,.section-block,.process-section,.split-section').forEach(s=>{if(!s.querySelector('.mtgx-section-glint')){const g=document.createElement('i');g.className='mtgx-section-glint';s.appendChild(g)}});if(lowPower||innerWidth<=700)return;const trail=Array.from({length:4},()=>{const d=document.createElement('i');d.className='mtgx-cursor-trail';document.body.appendChild(d);return{el:d,x:-100,y:-100}});let mx=-100,my=-100,active=true;document.addEventListener('visibilitychange',()=>active=!document.hidden);addEventListener('pointermove',e=>{mx=e.clientX;my=e.clientY;trail.forEach(t=>t.el.style.opacity='.55')},{passive:true});let last=0;const tick=t=>{if(t-last>32&&active){last=t;let x=mx,y=my;trail.forEach((dot,i)=>{dot.x+=(x-dot.x)*(.28-i*.025);dot.y+=(y-dot.y)*(.28-i*.025);dot.el.style.left=`${dot.x}px`;dot.el.style.top=`${dot.y}px`;x=dot.x;y=dot.y})}requestAnimationFrame(tick)};requestAnimationFrame(tick)})();
